export const BUILTIN_NODES: BuiltinNode[] = bundledNodeDefinitions.map((d) => ({
  id: d.id,
  name: BUILTIN_COPY[d.id]?.name ?? d.name,
  description: BUILTIN_COPY[d.id]?.line ?? d.description,
  category: BUILTIN_COPY[d.id]?.category ?? d.category,
}))

